-- ============================================================================
-- CANONICAL AVAILABILITY SUPPLY REGRESSION
-- (supabase/migrations/20261012000000_intelligence_canonical_availability.sql)
--
-- Run by run-availability-canonical-pg.sh against a throwaway PostgreSQL seeded with
-- schema_availability_canonical.sql + the matrix generated by gen-availability-matrix.mjs.
--
-- The matrix is EVERY market_status (7) x EVERY unit configuration (15) -- 105 properties, plus draft/archived variants --
-- and the expected availability of each is computed by the BROWSER resolver (property-availability.js). Each property sits
-- in its own district, so `available_by_segment` / `available_by_bedroom_segment` say per property whether the SQL counted
-- it, and `available_unit_types` says which units. Any divergence between the SQL port and the browser rules fails here.
-- ============================================================================
\set ON_ERROR_STOP on
\set QUIET on

CREATE OR REPLACE FUNCTION assert(p_condition boolean, p_what text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF p_condition IS NOT TRUE THEN RAISE EXCEPTION 'REGRESSION FAILED: %', p_what; END IF;
  RAISE NOTICE '  ok  %', p_what;
END $$;

\echo '=== every market_status x unit-configuration state matches the browser resolver ==='
DO $$
DECLARE
  snap jsonb; seg jsonb; bed jsonb; uts jsonb;
  r record; got boolean; got_bed boolean; checked int := 0; mismatches text := '';
  expected_open int := 0; got_open int;
BEGIN
  snap := point_in_time_supply_snapshot();
  seg := snap->'active_inventory'->'available_by_segment';
  bed := snap->'active_inventory'->'available_by_bedroom_segment';
  uts := snap->'active_inventory'->'available_unit_types';

  FOR r IN SELECT * FROM expected_state ORDER BY district LOOP
    got     := (seg->>('for_rent|house|' || r.district))::int IS NOT NULL;
    got_bed := (bed->>('for_rent|' || r.district || '|2'))::int IS NOT NULL;
    IF got IS DISTINCT FROM r.expect_available OR got_bed IS DISTINCT FROM r.expect_available THEN
      mismatches := mismatches || format(E'\n    %s: SQL segment=%s bedroom_segment=%s, browser resolver available=%s', r.label, got, got_bed, r.expect_available);
    END IF;
    IF (SELECT count(*) FROM jsonb_object_keys(uts) k WHERE k = ANY(r.expect_open_units)) <> coalesce(array_length(r.expect_open_units, 1), 0) THEN
      mismatches := mismatches || format(E'\n    %s: available_unit_types does not contain exactly the browser resolver''s open units %s', r.label, r.expect_open_units);
    END IF;
    expected_open := expected_open + coalesce(array_length(r.expect_open_units, 1), 0);
    checked := checked + 1;
  END LOOP;

  PERFORM assert(mismatches = '', 'every state agrees with the browser resolver' || mismatches);
  PERFORM assert(checked = 111, format('checked all 111 states (105 market x unit-set + 6 draft/archived variants), got %s', checked));

  -- nothing EXTRA in available_unit_types (a unit of an unavailable property must never leak in)
  SELECT count(*) INTO got_open FROM jsonb_object_keys(uts);
  PERFORM assert(got_open = expected_open, format('available_unit_types holds exactly the %s open units of available properties (got %s)', expected_open, got_open));
END $$;

\echo ''
\echo '=== the named rules, each on a concrete property ==='
DO $$
DECLARE seg jsonb; uts jsonb;
BEGIN
  seg := point_in_time_supply_snapshot()->'active_inventory'->'available_by_segment';
  uts := point_in_time_supply_snapshot()->'active_inventory'->'available_unit_types';
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'coming_soon/twoOpen/active') IS NULL, 'coming_soon is NOT supply even with open units');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'sold/oneOpen/active') IS NULL, 'sold is NOT supply even with an open unit');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'off_market/twoOpen/active') IS NULL, 'off_market is NOT supply even with open units');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'rented/oneOpen/active') IS NULL, 'single-unit rented is NOT supply: the property status wins over a lone open unit');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'reserved/oneOpen/active') IS NULL, 'single-unit reserved is NOT supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'fully_occupied/oneOpen/active') IS NULL, 'single-unit fully_occupied is NOT supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'rented/openAndFull/active') = 1, 'multi-unit rented WITH an open unit IS supply (unit level)');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'rented/twoFull/active') IS NULL, 'multi-unit rented with no open unit is NOT supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'available/twoFull/active') IS NULL, 'market_status=available but every unit closed is NOT supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'available/oneFull/active') IS NULL, 'market_status=available with a closed lone unit is NOT supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'available/none/active') = 1, 'market_status=available with no unit rows IS supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'available/oneOpenDated/active') = 1, 'an open unit with a next_available_date is still open (the date is display-only)');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'available/oneFull/active') IS NULL, 'a closed unit with a future next_available_date does NOT become supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'available/none/draft') IS NULL, 'a draft property is never supply');
  PERFORM assert((SELECT (seg->>('for_rent|house|' || district))::int FROM expected_state WHERE label = 'available/twoOpen/archived') IS NULL, 'an archived property is never supply');
END $$;

\echo ''
\echo '=== the active-inventory population and every other key are untouched ==='
DO $$
DECLARE snap jsonb;
BEGIN
  snap := point_in_time_supply_snapshot();
  PERFORM assert((snap->'active_inventory'->>'total')::int = (SELECT count(*) FROM properties WHERE status IN ('active', 'available')),
    'active_inventory.total still counts the legacy status IN (active, available) population (105 here), whatever the market_status');
  PERFORM assert(snap->'active_inventory' ?& ARRAY['total','by_property_type','by_district','by_segment','available_by_segment','available_by_bedroom_segment','available_unit_types'], 'all seven active_inventory keys present');
  PERFORM assert(snap ? 'asking_price', 'asking_price key present');
  PERFORM assert((snap->'active_inventory'->'by_segment'->>'for_rent|house|D001')::int = 1, 'by_segment still counts a sold/rented/closed property as inventory (D001 here)');
  PERFORM assert((snap->'active_inventory'->'by_segment'->>'for_rent|house|D005')::int = 1, 'by_segment counts the market_status=available / oneSoon property even though it is not bookable supply');
END $$;

\echo ''
\echo '=== ACL is preserved by CREATE OR REPLACE (still not executable by anon / authenticated / PUBLIC) ==='
DO $$
BEGIN
  PERFORM assert(NOT has_function_privilege('anon', 'point_in_time_supply_snapshot()', 'EXECUTE'), 'anon cannot execute it');
  PERFORM assert(NOT has_function_privilege('authenticated', 'point_in_time_supply_snapshot()', 'EXECUTE'), 'authenticated cannot execute it');
  PERFORM assert(NOT EXISTS (SELECT 1 FROM pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                              WHERE p.oid = 'point_in_time_supply_snapshot()'::regprocedure AND a.grantee = 0 AND a.privilege_type = 'EXECUTE'),
                 'PUBLIC cannot execute it');
  PERFORM assert((SELECT prosecdef FROM pg_proc WHERE oid = 'point_in_time_supply_snapshot()'::regprocedure), 'SECURITY DEFINER');
  PERFORM assert((SELECT proconfig FROM pg_proc WHERE oid = 'point_in_time_supply_snapshot()'::regprocedure) = ARRAY['search_path=public'], 'search_path = public');
  PERFORM assert((SELECT count(*) FROM pg_proc WHERE proname = 'point_in_time_supply_snapshot') = 1, 'exactly one overload');
END $$;

\echo ''
\echo '=== read-only: the function changed nothing ==='
DO $$
BEGIN
  PERFORM assert((SELECT count(*) FROM properties) = 111, 'no property row was added or removed');
END $$;
